+
+                if (areaTriggerTemplate.Type == (byte)AreaTriggerType.Cylinder)
+                {
+                    areaTriggerTemplate.Data[0] = packet.ReadSingle("Radius", index);
+                    areaTriggerTemplate.Data[1] = packet.ReadSingle("RadiusTarget", index);
